@@ -39,8 +39,26 @@ const int shmem_size_block_gemm = (SUB_N_BLOCK / NUM_PIPE_N_BLOCK) * (K_BLOCK /

 #define BLOCKS_PER_GRID 16384

+#include "solver_extensions/register_gemm.cuh"
+#include "solver_extensions/edge.cuh"
+
 __global__ void block_gemm_1d_double_mma(const double *A, const double *B, double *C, const double alpha, const double beta)
 {
+    constexpr int warps_n = (M_BLOCK >= 32 && N_BLOCK % 16 == 0) ? 2 : 1;
+    constexpr bool full_tiles = K_BLOCK % 8 == 0 && N_BLOCK % (8 * warps_n) == 0 &&
+                                M_BLOCK % (16 * (NUM_ALLOC_RANK_BLOCK / warps_n)) == 0;
+    if constexpr (full_tiles) {
+        if constexpr (M_BLOCK >= 128 || (M_BLOCK == 16 && K_BLOCK >= 32) ||
+                      (M_BLOCK == 64 && K_BLOCK >= 64)) {
+            warp_gemm::prefetch_lines<M_BLOCK * K_BLOCK>(A);
+            warp_gemm::prefetch_lines<N_BLOCK * K_BLOCK>(B);
+        }
+        if constexpr (M_BLOCK >= 128 && K_BLOCK <= 32)
+            warp_gemm::prefetch_lines<M_BLOCK * N_BLOCK>(C);
+        warp_gemm::run<warps_n>(A, B, C, alpha, beta);
+    } else {
+        edge_gemm(A, B, C, alpha, beta);
+    }
 }

 int main(int argc, char *argv[])
